public async Task UpdatePostTitleAsync(
    BlogContext context,
    int id,
    string newTitle,
    CancellationToken cancellationToken = default)
{
    var postQuery = from post in context.Posts
                    where post.Id == id
                    select post;

    var post = await postQuery.FirstOrDefaultAsync(cancellationToken);

    if (post is not null)
    {
        post.Title = newTitle;
        await context.SaveChangesAsync(cancellationToken);
    }
}
